bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createVideoInvoiceSalesFlow} from './src/telegram/videoInvoiceSales.mjs';
import {createPostgresVideoInvoiceStore} from './src/sales/pgVideoInvoiceOrders.mjs';
const e=process.env;
if(e.VIDEOBOT_DB_NAME!=='videobot')throw Error('VIDEO_BUYER_DB_OWNER_MISMATCH');
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
const net=createCreatorTelegramFetch();
try{
 const reissue=(await pool.query("SELECT l.status,r.sale_mode,r.status receipt_status FROM videobot_listings l JOIN videobot_post_receipts r ON l.listing_id=r.listing_id WHERE l.listing_id='v26nov24invoice'")).rows;
 if(reissue.length!==1||reissue[0].status!=='published'||reissue[0].sale_mode!=='invoice'||reissue[0].receipt_status!=='sent')throw Error('NEW_INVOICE_OFFER_NOT_VERIFIED');
 const buyer=(await pool.query("SELECT DISTINCT p.buyer_user_id FROM videobot_stars_ledger p JOIN videobot_listings old ON old.listing_id=p.listing_id JOIN videobot_listings newer ON newer.seller_user_id=old.seller_user_id AND newer.paid_video_file_id=old.paid_video_file_id WHERE p.kind='paid' AND newer.listing_id='v26nov24invoice'")).rows;
 if(buyer.length!==1)throw Error('HISTORIC_BUYER_CARDINALITY_UNVERIFIED');
 const buyerId=Number(buyer[0].buyer_user_id);
 if(!Number.isSafeInteger(buyerId)||buyerId<=0)throw Error('HISTORIC_BUYER_ID_INVALID');
 const store=createPostgresVideoInvoiceStore(pool);
 const original=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000});
 const api=async(method,params)=>{if(method!=='sendVideo'||params?.chat_id!==buyerId||params?.protect_content!==false)throw Error('HISTORIC_BUYER_ONLY_VIDEO_DELIVERY_ALLOWED');return original(method,params)};
 const old=(await pool.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 const result=await createVideoInvoiceSalesFlow({api,store}).purchase(buyerId,'v26nov24invoice',1);
 const state=(await pool.query("SELECT status,delivered_message_id FROM videobot_video_legacy_deliveries WHERE delivery_key='v26nov24invoice:1' AND buyer_user_id=$1",[buyerId])).rows[0];
 const newPaid=(await pool.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 console.log('LEGACY_BUYER_RESULT='+JSON.stringify({alreadyPurchased:result.alreadyPurchased===true,delivered:result.delivered===true,deliveryUnknown:result.deliveryUnknown===true,state:state?.status??null,hasDeliveryMessage:state?.delivered_message_id!=null,ledgerUnchanged:old===newPaid}));
 if(result.alreadyPurchased!==true||result.delivered!==true||state?.status!=='delivered'||state?.delivered_message_id==null||old!==newPaid)throw Error('LEGACY_BUYER_FULL_VIDEO_NOT_VERIFIED_KEEP_OLD_POST');
}finally{await net.close();await pool.end()}
NODE
